SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, l.labevent_id, l.itemid, l.value, l.valuenum, l.valueuom, l.flag, l.priority, l.comments, m.microevent_id, m.test_seq, m.test_itemid, m.test_name, m.org_itemid, m.org_name, m.isolate_num, m.quantity, m.ab_itemid, m.ab_name, m.dilution_text, m.dilution_comparison, m.dilution_value, m.interpretation, m.comments, COUNT(DISTINCT l.labevent_id) AS num_lab_events, COUNT(DISTINCT m.microevent_id) AS num_micro_events, (COUNT(DISTINCT l.labevent_id) + COUNT(DISTINCT m.microevent_id)) AS total_events, (a.dischtime - a.admittime) AS length_of_stay, (CASE WHEN a.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS is_dead FROM patients p JOIN admissions a ON p.subject_id = a.subject_id LEFT JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id LEFT JOIN microbiologyevents m ON a.subject_id = m.subject_id AND a.hadm_id = m.hadm_id AND m.test_seq = 1 WHERE p.gender = 'M' AND p.anchor_age = 42 AND p.anchor_year = 2017 AND p.anchor_year_group = '47-52' AND a.admittime <= '2017-01-01 00:00:00' AND (a.dischtime >= '2017-01-01 00:00:00' OR a.dischtime IS NULL) AND (a.deathtime >= '2017-01-01 00:00:00' OR a.deathtime IS NULL) AND (l.flag = 'A' OR l.flag = 'W') AND (m.interpretation = 'S' OR m.interpretation = 'R') GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, l.labevent_id, l.itemid, l.value, l.valuenum, l.valueuom, l.flag, l.priority, l.comments, m.microevent_id, m.test_seq, m.test_itemid, m.test_name, m.org_itemid, m.org_name, m.isolate_num, m.quantity, m.ab_itemid, m.ab_name, m.dilution_text, m.dilution_comparison, m.dilution_value, m.interpretation, m.comments ORDER BY total_events DESC NULLS LAST;